<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();$sid=(int)($_GET['service']??$_POST['service_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['a']??'';if($a==='add'){$key=preg_replace('/[^a-zA-Z0-9_]/','_',trim($_POST['field_key']));$opts=trim($_POST['options']??'');$p->prepare("INSERT INTO service_fields(service_id,label,field_key,field_type,options_json,is_required,sort_order)VALUES(?,?,?,?,?,?,?)")->execute([$sid,trim($_POST['label']),$key,$_POST['field_type'],$opts?json_encode(array_map('trim',explode(',',$opts)),JSON_UNESCAPED_UNICODE):null,!empty($_POST['required'])?1:0,(int)$_POST['sort_order']]);}if($a==='del')$p->prepare("DELETE FROM service_fields WHERE id=?")->execute([(int)$_POST['id']]);}$q=$p->prepare("SELECT * FROM services WHERE id=?");$q->execute([$sid]);$service=$q->fetch();$q=$p->prepare("SELECT * FROM service_fields WHERE service_id=? ORDER BY sort_order,id");$q->execute([$sid]);$rows=$q->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>فیلدساز</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1000px;margin:30px auto}.card{background:#fff;padding:22px;border-radius:18px;margin:15px 0}input,select{width:100%;box-sizing:border-box;padding:11px;margin:7px 0}button{background:#1687d9;color:#fff;border:0;padding:10px 14px;border-radius:8px}.danger{background:#d9534f}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eee}</style><div class=wrap><a href=/admin/services.php>← خدمات</a><?php if(!$service):?><div class=card>خدمت نامعتبر است.</div><?php else:?><div class=card><h3>🧩 فیلدساز: <?=e($service['name'])?></h3><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=add><input type=hidden name=service_id value=<?=$sid?>><input name=label placeholder="عنوان فیلد؛ مثلاً کد ملی" required><input name=field_key placeholder="کلید انگلیسی؛ مثلاً national_code" required><select name=field_type><option value=text>متن</option><option value=number>عدد</option><option value=phone>موبایل</option><option value=textarea>توضیحات</option><option value=select>انتخابی</option><option value=file>فایل</option><option value=image>تصویر</option></select><input name=options placeholder="گزینه‌ها برای انتخابی: گزینه ۱,گزینه ۲"><label><input type=checkbox name=required checked> الزامی</label><input type=number name=sort_order value=0><button>افزودن فیلد</button></form></div><div class=card><table><tr><th>عنوان</th><th>کلید</th><th>نوع</th><th>الزامی</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['label'])?></td><td><?=e($r['field_key'])?></td><td><?=e($r['field_type'])?></td><td><?=$r['is_required']?'بله':'خیر'?></td><td><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=del><input type=hidden name=id value=<?=$r['id']?>><button class=danger>حذف</button></form></td></tr><?php endforeach;?></table></div><?php endif;?></div>
